        return lastDayOfLastMonth;
    }

    static totalDaysInMonth() {
        return (
            Math.round(
                Math.abs(
                    (DatetimeUtils.firstDayOfMonth().getTime() - DatetimeUtils.lastDayOfMonth().getTime()) /
                        DatetimeUtils.oneDay
                )
            ) + 1
        );
    }

