export const retryAndBackoff = async (fn: () => Promise<any>, retries: number, backoff: number) => {
    let lastError;
    for (let i = 0; i < retries; i++) {
        try {
            return await fn();
        } catch (err) {
            lastError = err;
            await new Promise((resolve) => setTimeout(resolve, backoff));
        }
    }
    throw lastError;
};

